      !['NATIVE_X402', 'CHALLENGE_ONLY', 'UNKNOWN'].includes(snapshot.mode) ||
      !Array.isArray(snapshot.routes) || snapshot.routes.length > 103 || !snapshot.routes.length)
    fail('Original SF30 traffic snapshot with UTC days required');
