    ...OUTCOMES, 'durationMeanMs', 'durationMaxMs', 'latencyP95UpperBoundMs', 'httpSuccessPercent'];
  const cell = value => {
    let text = value === null || value === undefined ? '' : String(value);
    if (/^[\s]*[=+\-@]/.test(text)) text = "'" + text;
    return '"' + text.replaceAll('"', '""') + '"';
