export const PYTHON_DOCUMENT_LIMITS=Object.freeze({
  documentBytes:32*1024*1024,originalBytes:32*1024*1024,totalBytes:256*1024*1024,
  originals:32,archivePartBytes:16*1024*1024,rows:1000000
